/**
 * Dialect pass, #1–#14 (see DIALECT-PASS.md / DIALECTS.md).
 * Silla 경주 경상 / clipped RP; Baekje 충청 / genteel Old South; Goguryeo 평안 / light Scots.
 * Court, councils, coronation, envoys and Heewon's emoji-labelled blocks stay standard.
 * Each edit is [oldKo, newKo, newEn?, person?]; it finds the one dialogue line in that episode whose Korean is exactly
 * oldKo and swaps it. Re-running skips lines already converted.
 */
import fs from 'node:fs';
import path from 'node:path';
import { editStory, lists, ROOT } from '../story-ops.mjs';

const src = fs.readFileSync(path.join(ROOT, 'src/lib/people.ts'), 'utf8');
const ids = [...src.matchAll(/^\t\tid:\s*'([^']+)'/gm)];
const KINGDOM = new Map();
ids.forEach((m, i) => {
	const k = src.slice(m.index, ids[i + 1]?.index ?? src.length).match(/\bkingdom:\s*'([^']+)'/)?.[1];
	if (k && !KINGDOM.has(m[1])) KINGDOM.set(m[1], k);
});

/** Episode setting for unnamed speakers and reused generic ids (`herald`, `courtmaid`). */
const SETTING = { 1: 'silla', 2: 'silla', 3: 'silla', 4: 'baekje', 5: 'baekje', 6: 'baekje', 7: 'goguryeo', 8: 'goguryeo', 9: 'silla', 10: 'silla', 11: 'silla', 12: 'silla', 13: 'silla', 14: 'silla' };
const GENERIC = new Set(['herald', 'courtmaid']);
function kingdomOf(n, b) {
	if (b.speaker) return /Goguryeo/.test(b.speaker) ? 'goguryeo' : /Silla/.test(b.speaker) ? 'silla' : SETTING[n];
	if (GENERIC.has(b.person)) return SETTING[n];
	return KINGDOM.get(b.person) ?? SETTING[n];
}

