function hits(entry, ko, person) {
	const out = [];
	for (const list of lists(entry))
		for (const b of list) {
			if (b.kind !== 'dialogue' || (person && b.person !== person)) continue;
			b.lines.forEach((l, j) => l === ko && out.push({ b, j }));
		}
	return out;
}

const tally = {};
let changed = 0;
let skipped = 0;
editStory((story) => {
	const all = story.flatMap((c) => c.entries);
	for (const [key, edits] of Object.entries(EDITS)) {
		const n = Number(key);
		const e = all[n - 1];
		for (const [oldKo, newKo, newEn, person] of edits) {
			const h = hits(e, oldKo, person);
			if (h.length === 0) {
				if (hits(e, newKo, person).length) {
					skipped++;
					continue;
				}
				throw new Error(`#${n} ${e.title}: not found "${oldKo}"`);
			}
			if (h.length > 1) throw new Error(`#${n} ${e.title}: ${h.length} matches for "${oldKo}"`);
			const { b, j } = h[0];
			b.lines[j] = newKo;
			if (newEn) b.en[j] = newEn;
			const k = kingdomOf(n, b);
			tally[k] = (tally[k] ?? 0) + 1;
			changed++;
		}
	}
	return changed > 0;
});
console.log(`changed ${changed}, already done ${skipped}`, tally);
